"""Persistent (immutable) ordered containers built with path copying.

Two primitives are provided:

* Treaps keyed by arbitrary totally ordered values.  Nodes are immutable
  5-tuples ``(key, priority, left, right, size)``; every operation returns a
  fresh root so that older roots keep describing older versions.  A snapshot
  of a container therefore costs O(1), which keeps branching (save/restore)
  independent of the size of the backlog.

* ``PTrie``: a persistent map over a *static* integer key domain.  It is used
  for the WFQ weight/finish tables whose keys are known when the run starts.

Everything here is exact integer arithmetic; no hashing of payloads and no
reliance on dictionary ordering is required for observable results.
"""

from random import Random

# A single deterministic generator supplies treap priorities.  Priorities only
# influence the *shape* of the trees, never the observable results, but a fixed
# seed keeps runs reproducible while debugging.
_GEN = Random(0x7C1F3E59A2DB)


def next_priority():
    return _GEN.getrandbits(30)


# --------------------------------------------------------------------------
# persistent treap
# --------------------------------------------------------------------------

def tsize(node):
    """Number of keys stored in the subtree ``node``."""
    return 0 if node is None else node[4]


def tinsert(node, key):
    """Return a new root with ``key`` inserted (duplicates allowed)."""
    if node is None:
        return (key, next_priority(), None, None, 1)
    k = node[0]
    if key < k:
        child = tinsert(node[2], key)
        if child[1] > node[1]:
            # rotate right: the freshly inserted node wins the heap property
            right = (k, node[1], child[3], node[3],
                     tsize(child[3]) + 1 + tsize(node[3]))
            return (child[0], child[1], child[2], right,
                    tsize(child[2]) + 1 + tsize(right))
        return (k, node[1], child, node[3], node[4] + 1)
    child = tinsert(node[3], key)
    if child[1] > node[1]:
        left = (k, node[1], node[2], child[2],
                tsize(node[2]) + 1 + tsize(child[2]))
        return (child[0], child[1], left, child[3],
                tsize(left) + 1 + tsize(child[3]))
    return (k, node[1], node[2], child, node[4] + 1)


def _merge(left, right):
    """Join two treaps; every key of ``left`` precedes every key of ``right``."""
    if left is None:
        return right
    if right is None:
        return left
    if left[1] >= right[1]:
        child = _merge(left[3], right)
        return (left[0], left[1], left[2], child,
                left[4] - tsize(left[3]) + tsize(child))
    child = _merge(left, right[2])
    return (right[0], right[1], child, right[3],
            right[4] - tsize(right[2]) + tsize(child))


def tdelete(node, key):
    """Return a new root without one occurrence of ``key``.

    When ``key`` is absent the very same node object is returned, so callers
    can detect absence with an identity test.
    """
    if node is None:
        return None
    k = node[0]
    if key < k:
        if node[2] is None:
            return node
        child = tdelete(node[2], key)
        if child is node[2]:
            return node
        return (k, node[1], child, node[3], node[4] - 1)
    if k < key:
        if node[3] is None:
            return node
        child = tdelete(node[3], key)
        if child is node[3]:
            return node
        return (k, node[1], node[2], child, node[4] - 1)
    return _merge(node[2], node[3])


def tpopmin(node):
    """Return ``(new_root, smallest_key)``; ``node`` must not be empty."""
    if node[2] is None:
        return node[3], node[0]
    child, key = tpopmin(node[2])
    return (node[0], node[1], child, node[3], node[4] - 1), key


def tcount_lt(node, key):
    """Number of stored keys strictly smaller than ``key``."""
    count = 0
    while node is not None:
        if node[0] < key:
            count += tsize(node[2]) + 1
            node = node[3]
        else:
            node = node[2]
    return count


def tcontains(node, key):
    while node is not None:
        k = node[0]
        if k < key:
            node = node[3]
        elif key < k:
            node = node[2]
        else:
            return True
    return False


def tkeys(node):
    """All keys in ascending order (used for final certificates)."""
    out = []
    stack = []
    cur = node
    while cur is not None or stack:
        while cur is not None:
            stack.append(cur)
            cur = cur[2]
        cur = stack.pop()
        out.append(cur[0])
        cur = cur[3]
    return out


# --------------------------------------------------------------------------
# persistent map over a static integer key domain
# --------------------------------------------------------------------------

def _trie_set(node, key, value, shift):
    if shift < 0:
        return (None, None, value)
    bit = (key >> shift) & 1
    if node is None:
        child = _trie_set(None, key, value, shift - 1)
        return (child, None, None) if bit == 0 else (None, child, None)
    if bit:
        return (node[0], _trie_set(node[1], key, value, shift - 1), node[2])
    return (_trie_set(node[0], key, value, shift - 1), node[1], node[2])


class PTrie:
    """Persistent ``int -> value`` map for keys in ``[0, 2**bits)``.

    ``set`` returns a new map; lookups are immutable and share structure with
    every version, which keeps WFQ table snapshots cheap.
    """

    __slots__ = ('root', 'bits')

    def __init__(self, bits, root=None):
        self.bits = bits
        self.root = root

    @classmethod
    def fromitems(cls, bits, items, default=None):
        root = None
        for key, value in items:
            root = _trie_set(root, key, value if value is not None else default,
                             bits - 1)
        return cls(bits, root)

    def get(self, key, default=None):
        node = self.root
        if node is None:
            return default
        shift = self.bits - 1
        while shift >= 0:
            node = node[(key >> shift) & 1]
            if node is None:
                return default
            shift -= 1
        return node[2] if node[2] is not None else default

    def set(self, key, value):
        return PTrie(self.bits,
                     _trie_set(self.root, key, value, self.bits - 1))
